CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE organizations (id text PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id text PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE sites (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations, data jsonb NOT NULL, current_plan_version integer NOT NULL DEFAULT 1, UNIQUE(id, organization_id));
CREATE TABLE memberships (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations, site_id text REFERENCES sites, user_id text NOT NULL REFERENCES users, role text NOT NULL CHECK (role IN ('org_admin','site_manager','planner','gate_operator','dock_operator','viewer')));
CREATE TABLE sessions (hashed_token text PRIMARY KEY, user_id text NOT NULL REFERENCES users, expires_at timestamptz NOT NULL);
CREATE TABLE carriers (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations, name text NOT NULL, contact_email text, external_ref text);
CREATE TABLE docks (id text PRIMARY KEY, site_id text NOT NULL REFERENCES sites, data jsonb NOT NULL, UNIQUE(id, site_id));
CREATE TABLE appointments (id text PRIMARY KEY, organization_id text NOT NULL, site_id text NOT NULL, external_id text, version integer NOT NULL DEFAULT 1, data jsonb NOT NULL, FOREIGN KEY (site_id, organization_id) REFERENCES sites(id, organization_id), UNIQUE(id, site_id), UNIQUE(organization_id, external_id));
CREATE INDEX appointments_site_idx ON appointments(site_id, ((data->>'status')));
CREATE TABLE visits (appointment_id text PRIMARY KEY REFERENCES appointments, data jsonb NOT NULL);
CREATE TABLE dock_allocations (id text PRIMARY KEY, appointment_id text NOT NULL, dock_id text NOT NULL, site_id text NOT NULL REFERENCES sites, start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, state text NOT NULL CHECK (state IN ('active','superseded')), plan_version integer NOT NULL, CHECK (end_at > start_at), FOREIGN KEY (appointment_id, site_id) REFERENCES appointments(id, site_id), FOREIGN KEY (dock_id, site_id) REFERENCES docks(id, site_id), CONSTRAINT no_double_booking EXCLUDE USING gist (dock_id WITH =, tstzrange(start_at, end_at, '[)') WITH &&) WHERE (state = 'active'));
CREATE UNIQUE INDEX one_active_allocation ON dock_allocations(appointment_id) WHERE state = 'active';
CREATE INDEX allocation_calendar_idx ON dock_allocations(site_id, start_at, end_at) WHERE state='active';
CREATE TABLE dock_blocks (id text PRIMARY KEY, dock_id text NOT NULL, site_id text NOT NULL, start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, data jsonb NOT NULL, CHECK (end_at > start_at), FOREIGN KEY (dock_id, site_id) REFERENCES docks(id, site_id));
CREATE TABLE plans (id text PRIMARY KEY, site_id text NOT NULL REFERENCES sites, version integer NOT NULL, previous_version integer NOT NULL, applied_at timestamptz NOT NULL DEFAULT now(), applied_by text NOT NULL, UNIQUE(site_id, version));
CREATE TABLE replan_proposals (id text PRIMARY KEY, site_id text NOT NULL REFERENCES sites, baseline_plan_version integer NOT NULL, snapshot_json jsonb NOT NULL, request_json jsonb NOT NULL, proposal_json jsonb NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','applied','rejected')), created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), applied_at timestamptz);
CREATE TABLE audit_events (id bigserial PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations, site_id text REFERENCES sites, actor text NOT NULL, source text NOT NULL, action text NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, before_json jsonb, after_json jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_site_idx ON audit_events(site_id, id);
CREATE FUNCTION forbid_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit_events is append-only'; END; $$;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION forbid_audit_mutation();
CREATE TABLE outbox_events (id bigserial PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations, site_id text REFERENCES sites, name text NOT NULL, payload_json jsonb NOT NULL, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_unpublished_idx ON outbox_events(id) WHERE published_at IS NULL;
CREATE TABLE webhook_endpoints (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations, url text NOT NULL, encrypted_secret text NOT NULL, active boolean NOT NULL DEFAULT true, event_filters text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_deliveries (id bigserial PRIMARY KEY, event_id bigint NOT NULL REFERENCES outbox_events, endpoint_id text NOT NULL REFERENCES webhook_endpoints, attempt integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'pending', next_attempt_at timestamptz NOT NULL DEFAULT now(), response_code integer, last_error text, UNIQUE(event_id, endpoint_id));
CREATE TABLE api_tokens (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations, site_id text REFERENCES sites, name text NOT NULL, hashed_token text NOT NULL UNIQUE, scopes text[] NOT NULL, expires_at timestamptz NOT NULL, last_used_at timestamptz, revoked_at timestamptz);
CREATE TABLE portal_tokens (id text PRIMARY KEY, appointment_id text REFERENCES appointments DEFERRABLE INITIALLY DEFERRED, site_id text NOT NULL REFERENCES sites, hashed_token text NOT NULL UNIQUE, scopes text[] NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz, revoked_at timestamptz);
CREATE TABLE idempotency_keys (organization_id text NOT NULL REFERENCES organizations, actor text NOT NULL, key text NOT NULL, request_hash text NOT NULL, response_json jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (organization_id, actor, key));
